// Method: BFS 
class Triple {
    int row;
    int col;
    int level;

    public Triple(int row, int col, int level) {
        this.row = row;
        this.col = col;
        this.level = level;
    }
}

class Solution {
    public int orangesRotting(int[][] grid) {
        if (grid == null || grid.length == 0) {
            return 0;
        }
        int m = grid.length;
        int n = grid[0].length;
        // Initialize the level to -1, since we only count the process as 1.
        int level = -1;
        // Count the fresh in total and check whether the fresh is 0 in the end.
        int fresh = 0;
        boolean[][] visited = new boolean[m][n];
        Queue<Triple> queue = new LinkedList<>();

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 2) {
                    queue.offer(new Triple(i, j, level));
                    visited[i][j] = true;  
                } else if (grid[i][j] == 1) {
                    fresh++;
                }
            }
        }

        // Edge cases.
        // When there's no fresh, return 0.
        if (fresh == 0) {
            return 0;
        }
        int[] directionX = {0, 0, 1, -1};
        int[] directionY = {1, -1, 0, 0};
        while (!queue.isEmpty()) {
            Triple t = queue.poll();
            int row = t.row;
            int col = t.col;
            level = t.level;
            level++;
            for (int k = 0; k < 4; k++) {
                int currRow = row + directionX[k];
                int currCol = col + directionY[k];
                if (currRow >= 0 && currRow < m && currCol >= 0 && currCol < n && grid[currRow][currCol] == 1 && visited[currRow][currCol] == false) {
                    grid[currRow][currCol] = 2;
                    fresh--;
                    visited[currRow][currCol] = true;
                    queue.offer(new Triple(currRow, currCol, level));
                }
            }
        }
        if (fresh == 0) {
            return level;
        }
        return -1;
    }
}
// Time Complexity: O(n)
// Space Complexity: O(n)
